+import tailwindcss, { type Config } from 'tailwindcss';
+import postcss from 'postcss';
+import { test, expect } from 'vitest';
+import StarlightTailwindPlugin from './index.ts';
+
+const gen = async ({ css = '@tailwind base;', html = '', config = {} }: any = {}): Promise<string> => {
+  const r = await postcss(tailwindcss({ plugins: [StarlightTailwindPlugin()], content: [{ raw: html, extension: 'html' }], ...config })).process(css, { from: '' });
+  return r.css;
+};
+
+test('dark selector format', async () => {
+  const utils = await gen({ css: '@tailwind utilities;', html: '<div class="dark:text-red-50"></div>' });
+  console.log('UTILS>>>\n' + utils + '\n<<<');
+  expect(utils).includes('.dark\\:text-red-50:is([data-theme="dark"] *)');
+  expect(utils).not.includes(':is([data-theme="dark"] .dark');
+});
+
+test('contain vars in base', async () => {
+  const base = await gen();
+  for (const p of ['--tw-contain-size', '--tw-contain-layout', '--tw-contain-paint', '--tw-contain-style']) {
+    // must appear in both * and ::backdrop blocks -> at least twice
+    const count = base.split(p).length - 1;
+    expect(count).toBeGreaterThanOrEqual(2);
+  }
+});
